import{_ as a,C as i,o as l,c as s,a2 as o,j as n,a as t,E as d}from"./chunks/framework.CtQGab4e.js";const f=JSON.parse('{"title":"Wat is er nieuw","description":"","frontmatter":{},"headers":[],"relativePath":"wat-is-er-nieuw.md","filePath":"wat-is-er-nieuw.md"}'),g={name:"wat-is-er-nieuw.md"};function p(k,e,h,m,u,v){const r=i("Icon");return l(),s("div",null,[e[6]||(e[6]=o('<h1 id="wat-is-er-nieuw" tabindex="-1">Wat is er nieuw <a class="header-anchor" href="#wat-is-er-nieuw" aria-label="Permalink to &quot;Wat is er nieuw&quot;">​</a></h1><h2 id="_0-1-0" tabindex="-1">0.1.0 <a class="header-anchor" href="#_0-1-0" aria-label="Permalink to &quot;0.1.0&quot;">​</a></h2><h3 id="november-2026" tabindex="-1">November 2026 <a class="header-anchor" href="#november-2026" aria-label="Permalink to &quot;November 2026&quot;">​</a></h3><ul><li><strong>Backup terugzetten.</strong> Importeer de backup-zip in één keer; je hoeft hem niet meer uit te pakken. Nieuwe notities komen voortaan bovenaan de lijst. Zie <a href="./tool/opslaan.html#importeren">Importeren</a>.</li><li><strong>Oriëntatie bevestigd.</strong> Een vergeten oriëntatie valt nu op: zonder dit vinkje in <strong>Eigenschappen</strong> kun je niet exporteren. Zie <a href="./plattegrond/gebouw.html#orientatie">Oriëntatie</a>.</li><li><strong>1,5m-lijnen in de PDF.</strong> Met de instelling <strong>1,5m-lijnen in PDF</strong> komen de 1,5m-lijnen in de PDF, met de lage stroken gearceerd. <strong>1,5m-lijnen intekenen</strong> is weg: intekenen is niet meer nodig. Zie <a href="./hoe-teken-ik/zadeldak.html#zolder-met-lage-delen">Zolder met lage delen</a>.</li><li><strong>Vloerbegrenzing.</strong> In de vlak-popup kies je waar een vloer aan grenst, bijvoorbeeld een vloer op zand of een zwevende erker. Boven een kelder is de vloer nu altijd onverwarmd. Zie <a href="./plattegrond/vlakken.html#vloerbegrenzing">Vloerbegrenzing</a>.</li><li><strong>Losse stukken van één gebouwdeel.</strong> Twee erkers van hetzelfde gebouwdeel krijgen in 3D nu allebei hun muren.</li><li><strong>Kozijnen en Label-wise.</strong> Voer de kozijnen in per constructie, met de hand of met een Bosch-meter via Bluetooth. Koppel ze in het 3D-paneel aan het model, en exporteer een importbestand voor Label-wise. Zie <a href="./plattegrond/kozijnen.html">Kozijnen invoeren</a>, <a href="./plattegrond/kozijnen-koppelen.html">Kozijnen koppelen</a> en <a href="./plattegrond/label-wise.html">Importeren in Label-wise</a>.</li><li><strong>Souterrain en dijkwoning.</strong> Een gevel kan nu aan <strong>Grond</strong> grenzen, helemaal, tot een hoogte of met een schuin aflopend maaiveld. Zie <a href="./hoe-teken-ik/souterrain.html">Souterrain of dijkwoning</a>.</li><li><strong>Auto-save naar een bestand.</strong> In Edge en Chrome houdt de tool een notitie op verzoek automatisch bij als JSON-bestand op schijf. Zie <a href="./tool/opslaan.html#auto-save-naar-een-bestand">Auto-save</a>.</li><li><strong>De tool als app op de iPad.</strong> Met <strong>Zet op beginscherm</strong> in Safari open je de tool over het hele scherm, met een eigen icoon. Let op de eigen opslag, zie <a href="./tool/scherm.html">Het scherm</a>.</li><li><strong>De tool als app op Windows.</strong> In Edge en Chrome installeer je de tool via <strong>Instellingen</strong>, zie <a href="./tool/instellingen.html#app">App</a>.</li><li><strong>Kelder eronder.</strong> Een onverwarmde kelder teken je nu op de begane grond, ook als hij boven de vloer uitsteekt. Zie <a href="./plattegrond/vlakken.html#kelder">Kelder</a>.</li><li><strong>Vloer boven maaiveld.</strong> Ligt een heel gebouwdeel hoger, dan vul je dat in bij de hoogtes van dat gebouwdeel. Zie <a href="./plattegrond/gebouw.html#gebouwdelen">Gebouwdelen</a>.</li><li><strong>Steekkap per kant.</strong> Een puntdak of steekkap kan per kant een eigen helling en goot hebben (<strong>Per kant afwijkend</strong>), zie <a href="./hoe-teken-ik/dakkapel.html#per-kant-een-andere-helling-of-goot">Steekkap</a>.</li><li><strong>3D-model in de teken-tool.</strong> In het <a href="./plattegrond/3d-paneel.html">3D-paneel</a> maak je met <strong>Genereer</strong> een 3D-model van je plattegrond, met per constructie de m². Je controleert en corrigeert de berekening (<a href="./plattegrond/constructies.html">Constructies en correcties</a>) en exporteert renders, de berekening en een interactieve weergave (<a href="./plattegrond/export-3d.html">Exporteren</a>).</li></ul><h3 id="oktober-2026" tabindex="-1">Oktober 2026 <a class="header-anchor" href="#oktober-2026" aria-label="Permalink to &quot;Oktober 2026&quot;">​</a></h3>',5)),n("ul",null,[e[5]||(e[5]=o('<li><strong>Dakkapellen.</strong> Met de knop <strong>Dakkapel</strong> in het dakpaneel van een gevel teken je een dakkapel, nokverhoging of steekkap: kies het type uit een lijst en vul de maten in bij de letters in de tekening. Zie <a href="./hoe-teken-ik/dakkapel.html">Dakkapel</a>.</li><li><strong>Splitsen in het midden of in drieën.</strong> In <strong>Meer opties</strong> van een muur splits je die precies in het midden, of in drieën met een middenstuk van een opgegeven breedte, met een korte hulplijn op elk splitspunt. Handig voor een dakkapel midden op een gevel. Zie <a href="./plattegrond/muren.html#splitsen">Splitsen</a>.</li><li><strong>Maat-pills bij hulplijnen</strong> zijn standaard verborgen; aanzetten kan bij de <a href="./tool/instellingen.html">instellingen</a>.</li>',3)),n("li",null,[e[0]||(e[0]=n("strong",null,"Handleiding.",-1)),e[1]||(e[1]=t(" Deze handleiding, te openen via het menu ",-1)),d(r,{name:"menu"}),e[2]||(e[2]=t(" → ",-1)),e[3]||(e[3]=n("strong",null,"Handleiding",-1)),e[4]||(e[4]=t(".",-1))])])])}const j=a(g,[["render",p]]);export{f as __pageData,j as default};
